]$n$::jsonb) as x(id text, rules jsonb, config jsonb)),
changed as (
  select s.* from src s join public.games g on g.id = s.id
  where not exists (select 1 from public.game_versions v where v.game_id = s.id and v.version = g.current_version
                    and v.rules = s.rules and v.config = s.config)),
ins as (
  insert into public.game_versions (game_id, version, rules, config, published_at)
  select c.id, coalesce((select max(version) from public.game_versions where game_id = c.id), 0) + 1, c.rules, c.config, now()
  from changed c returning game_id, version),
up as (update public.games g set current_version = ins.version from ins where g.id = ins.game_id returning true as inserted)
insert into public.catalogue_imports (content_version, report)
select $n$2.1.0$n$, jsonb_build_object('partie', $n$famille 2$n$, 'section', $n$versions de règles$n$,
  'ajouts', count(*) filter (where inserted), 'mises_a_jour', count(*) filter (where not inserted)) from up;

-- Activités dotées d'un moteur : jouables.
with up as (update public.games set implementation = 'playable'
            where id in ($n$N2-016$n$, $n$N2-017$n$, $n$N2-018$n$, $n$N2-019$n$, $n$N2-020$n$, $n$N2-021$n$, $n$N2-022$n$, $n$N2-023$n$, $n$N2-024$n$, $n$N2-025$n$, $n$N2-026$n$, $n$N2-027$n$, $n$N2-028$n$, $n$N2-029$n$, $n$N2-030$n$, $n$N2-124$n$, $n$N2-125$n$, $n$N2-126$n$) and implementation <> 'playable' returning true as inserted)
insert into public.catalogue_imports (content_version, report)
select $n$2.1.0$n$, jsonb_build_object('partie', $n$famille 2$n$, 'section', $n$activités jouables$n$,
  'ajouts', count(*) filter (where inserted), 'mises_a_jour', count(*) filter (where not inserted)) from up;

